<?php $count=1; while($p=$patients->fetch_assoc()): $appt_display='N/A'; if($p['appointment_date']){$appt_time=strtotime($p['appointment_date']);if($appt_time>time())$appt_display='<span class="appointment-badge appointment-pending">Scheduled<span>'.date('M d, H:i',$appt_time).'</span></span>';else$appt_display='<span class="appointment-badge appointment-done">Past<span>'.date('M d, H:i',$appt_time).'</span></span>';} ?>
